def build_agent(sandbox):
    # Beam dimensions and positions
    beam_w = 0.6
    beam_h = 0.3
    centers_x = [2.0, 3.2, 4.4, 5.6, 6.8]
    y_center = 1.5  # Elevated for better buoyancy
    bodies = []

    for x in centers_x:
        if x == 4.4:
            # Central beam with higher density for ballast
            b = sandbox.add_beam(x, y_center, beam_w, beam_h, angle=0, density=15.0)
        else:
            b = sandbox.add_beam(x, y_center, beam_w, beam_h, angle=0, density=10.0)
        sandbox.set_material_properties(b, restitution=0.05)
        bodies.append(b)

    # Connect beams with rigid joints
    for i in range(len(bodies) - 1):
        anchor_x = (centers_x[i] + centers_x[i + 1]) / 2
        sandbox.add_joint(bodies[i], bodies[i + 1], (anchor_x, y_center), type='rigid')

    return bodies[-1]

