def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    front_x = sandbox.get_vehicle_front_x() or agent_body.position.x
    target_x = 26.0

    if front_x >= target_x + 0.1:
        for b in sandbox.bodies:
            if b.active:
                b.linearVelocity = (0, 0)
                b.angularVelocity = 0
        return

    # Determine if in water
    in_water = front_x >= 10.0
    in_deep_channel = (16.5 <= front_x <= 19.5)
    beams = sandbox.bodies

    # Apply thrust to front beams on the bank
    if not in_water:
        # Apply thrust to front beams (5.6 and 6.8) to move into water
        for i, beam in enumerate(beams):
            if beam.position.x >= 5.6:  # only apply to front beams
                # Stagger thrust application with cooldown
                if step_count % 3 == i % 3:
                    sandbox.apply_force(beam, 520.0, 0.0, step_count)
    else:
        # Apply thrust to all beams in the water
        for i, beam in enumerate(beams):
            if beam.position.x < 10.0:
                continue  # only apply to beams in the water
            # Stagger thrust application with cooldown
            if step_count % 3 == i % 3:
                sandbox.apply_force(beam, 520.0, 0.0, step_count)
                # Apply lift in deep channel to counteract reduced buoyancy
                if in_deep_channel:
                    sandbox.apply_force(beam, 0.0, 400.0, step_count)
